#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int* parseNumbers(const char* s, int* n) {
    int cap = 16, size = 0;
    int* a = malloc(cap * sizeof(int));
    for (int i = 0; s[i]; ) {
        if (s[i] == '-' || isdigit((unsigned char)s[i])) {
            int sign = 1;
            if (s[i] == '-') { sign = -1; ++i; }
            if (isdigit((unsigned char)s[i])) {
                int x = 0;
                while (isdigit((unsigned char)s[i])) {
                    x = x * 10 + (s[i] - '0');
                    ++i;
                }
                if (size == cap) {
                    cap *= 2;
                    a = realloc(a, cap * sizeof(int));
                }
                a[size++] = sign * x;
            }
        } else ++i;
    }
    *n = size;
    return a;
}

void generateSubsets(int* nums, int n) {
    int total = 1 << n;
    printf("[");
    for (int mask = 0; mask < total; ++mask) {
        if (mask) printf(",");
        printf("[");
        int first = 1;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                if (!first) printf(",");
                printf("%d", nums[i]);
                first = 0;
            }
        }
        printf("]");
    }
    printf("]\n");
}

int main(void) {
    char input[1000000];
    if (!fgets(input, sizeof(input), stdin)) return 0;
    int n = 0;
    int* nums = parseNumbers(input, &n);
    generateSubsets(nums, n);
    free(nums);
    return 0;
}

